ImGui.SetWindowFontScale(1.26)
local x,y=ImGui.GetCursorScreenPos()
local avail=ImGui.GetContentRegionAvail()
local total=ImGui.CalcTextSize(name)or 0
local start_x=x+math.max(0.0,(avail-total)*0.5)
ImGui.PushStyleColor(ImGuiCol.Text,0,0,0,0)
ImGui.Text(name)
ImGui.PopStyleColor(1)
local t=((Time.GetEpocheMs()%2600)/2600)*6.28318530718
local dx=0.0
for i=1,#name do
local ch=string.sub(name,i,i)
local wave=(math.sin(t+((i-1)*.52))+1)*.5
local g=math.floor(184+(71*wave))
local b=math.floor(3+(35*wave))
ImGui.AddText(start_x+dx,y,ch,255,g,b,255)
dx=dx+(ImGui.CalcTextSize(ch)or 0)
end
ImGui.SetWindowFontScale(1.0)
end
